/**
 * LE PAQUET DÉRIVÉ — `libs-data.js`, imprimé depuis le registre du compilateur.
 *
 * Usage : node src/transpiler/libs-bundle.js > src/transpiler/libs-data.js
 *
 * ⛔ CE FICHIER NE CONSTRUIT PLUS RIEN. Le compilateur lit ses librairies dans leurs sources
 * (`librairies.js`, par point fixe, depuis un registre vide) ; ce script se contente d'imprimer ce que
 * le registre porte, dans l'ordre des noms, pour les consommateurs qui lisent encore le paquet. Le
 * paquet est un CACHE DÉRIVÉ, et il sort avec ses derniers lecteurs (décision du 2026-08-30, phase 5 —
 * Romain : « je veux pas de ce format intermédiaire »). Une seule construction, un seul interprète :
 * ce qui est imprimé ici est exactement ce que le compilateur lit.
 *
 * ⚠️ IL N'ÉCRIT JAMAIS SUR LE DISQUE — il rend son résultat sur la sortie standard, et c'est ce qui
 * rend le garde de fraîcheur possible : il relance ce script et compare à ce qui est commité.
 *
 * ⛔ L'ORDRE DU PAQUET EST CELUI DES NOMS, JAMAIS CELUI DES PASSES — ET IL DÉSIGNE UNE AUTORITÉ :
 * `motsDInvocation()` prend le PREMIER fichier qui sert un axe comme catalogue de référence. Un tri
 * par nom rend le paquet indifférent au format de chaque source.
 */
import './index.js';   // la porte : elle branche le compilateur sur son chargeur
import { leRegistre, placesDesLibrairies } from './libs.js';

const registre = leRegistre();

let output = '// Auto-generated by libs-bundle.js — do not edit\n';
output += '// Contains every library of lib/, whatever the format of its source\n\n';
output += 'const LIBS = {};\n\n';
for (const [name, data] of Object.entries(registre).sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))) {
  output += `LIBS["${name}"] = ${JSON.stringify(data)};\n\n`;
}

// ⛔ CHAQUE CLÉ PUBLIÉE PORTE SON ENTRÉE, VIDE SI ELLE N'A AUCUNE PLACE : « je n'ai pas de place » se
// distingue de « je n'ai rien déclaré ». Les places se publient parce qu'un consommateur ne peut pas
// les déduire ; `_deduites` nomme les catalogues encore en JSON, où sa confiance s'arrête.
const PLACES = placesDesLibrairies(registre);
const deduites = PLACES._deduites;
delete PLACES._deduites;
output += `const PLACES = ${JSON.stringify(PLACES)};\n`;
output += `PLACES._deduites = ${JSON.stringify(deduites)};\n\n`;
output += 'export { LIBS, PLACES };\n';

process.stdout.write(output);
